using Microsoft.AspNetCore.Mvc; using Exercicio14_Cursos.Models; namespace Exercicio14_Cursos.Controllers; public class CursoController:Controller{private static readonly List<Curso> Dados=new(){new(){Id=1,Nome="Curso 1",CargaHoraria=25,Modalidade="Online",Vagas=11,Valor=130},new(){Id=2,Nome="Curso 2",CargaHoraria=30,Modalidade="Presencial",Vagas=12,Valor=160},new(){Id=3,Nome="Curso 3",CargaHoraria=35,Modalidade="Online",Vagas=13,Valor=190},new(){Id=4,Nome="Curso 4",CargaHoraria=40,Modalidade="Presencial",Vagas=0,Valor=220},new(){Id=5,Nome="Curso 5",CargaHoraria=45,Modalidade="Online",Vagas=15,Valor=250},new(){Id=6,Nome="Curso 6",CargaHoraria=50,Modalidade="Presencial",Vagas=16,Valor=280},new(){Id=7,Nome="Curso 7",CargaHoraria=55,Modalidade="Online",Vagas=17,Valor=310},new(){Id=8,Nome="Curso 8",CargaHoraria=60,Modalidade="Presencial",Vagas=0,Valor=340},new(){Id=9,Nome="Curso 9",CargaHoraria=65,Modalidade="Online",Vagas=19,Valor=370},new(){Id=10,Nome="Curso 10",CargaHoraria=70,Modalidade="Presencial",Vagas=20,Valor=400},}public IActionResult Index()=>View(Dados); public IActionResult Disponiveis()=>View("Index",Dados.Where(x=>x.Vagas>0)); public IActionResult Online()=>View("Index",Dados.Where(x=>x.Modalidade=="Online")); public IActionResult Presenciais()=>View("Index",Dados.Where(x=>x.Modalidade=="Presencial")); public IActionResult Dashboard()=>View(Dados);}
